if (grim_interface_ptr->grim_is_key_down(0x3b)) {
    show_play_counts = true;
    grim_interface_ptr->grim_draw_text_small_fmt(
        position.x + 132.0f,
        position.y + 16.0f,
        "times played:");
}

bool roomy_layout =
    quest_unlock_index < 0x28 || config_player_count > 1;
if (roomy_layout) {
    position.y += 32.0f;
    if (mode_play_rush + quest_play_counts[11] + mode_play_survival <= 0) {
        if (config_player_count == 1) {
            ui_button_update(
                (float *)&position, (ui_button_t *)&tutorial_button);
        }
        position.y += 32.0f;
    }

    ui_button_update((float *)&position, (ui_button_t *)&quests_button);
    if (show_play_counts) {
        grim_interface_ptr->grim_draw_text_small_fmt(
            position.x + 158.0f,
            position.y + 8.0f,
            "%d",
            play_game_quest_count());
    }
    position.y += 32.0f;

    ui_button_update((float *)&position, (ui_button_t *)&rush_button);
    if (show_play_counts) {
        grim_interface_ptr->grim_draw_text_small_fmt(
            position.x + 158.0f,
            position.y + 8.0f,
            "%d",
            mode_play_rush);
    }
    position.y += 32.0f;

    ui_button_update((float *)&position, (ui_button_t *)&survival_button);
    if (show_play_counts) {
        grim_interface_ptr->grim_draw_text_small_fmt(
            position.x + 158.0f,
            position.y + 8.0f,
            "%d",
            mode_play_survival);
    }
    position.y += 32.0f;

    if (quest_play_counts[11] + mode_play_survival + mode_play_rush > 0) {
        if (config_player_count == 1) {
            ui_button_update(
                (float *)&position, (ui_button_t *)&tutorial_button);
        }
        position.y += 32.0f;
    }
} else {
    position.y += 26.0f;
    if (quest_play_counts[11] + mode_play_survival + mode_play_rush <= 0) {
        if (config_player_count == 1) {
            ui_button_update(
                (float *)&position, (ui_button_t *)&tutorial_button);
        }
        position.y += 28.0f;
    }

    ui_button_update((float *)&position, (ui_button_t *)&quests_button);
    if (show_play_counts) {
        grim_interface_ptr->grim_draw_text_small_fmt(
            position.x + 158.0f,
            position.y + 8.0f,
            "%d",
            play_game_quest_count());
    }
    position.y += 28.0f;

    ui_button_update((float *)&position, (ui_button_t *)&rush_button);
    if (show_play_counts) {
        grim_interface_ptr->grim_draw_text_small_fmt(
            position.x + 158.0f,
            position.y + 8.0f,
            "%d",
            mode_play_rush);
    }
    position.y += 28.0f;

    ui_button_update((float *)&position, (ui_button_t *)&survival_button);
    if (show_play_counts) {
        grim_interface_ptr->grim_draw_text_small_fmt(
            position.x + 158.0f,
            position.y + 8.0f,
            "%d",
            mode_play_survival);
    }
    position.y += 28.0f;

    if (game_is_full_version()) {
        if (config_player_count == 1) {
            ui_button_update(
                (float *)&position, (ui_button_t *)&typo_button);
        }
        if (show_play_counts) {
            grim_interface_ptr->grim_draw_text_small_fmt(
                position.x + 158.0f,
                position.y + 8.0f,
                "%d",
                mode_play_typo);
        }
    }
    position.y += 28.0f;

    if (quest_play_counts[11] + mode_play_survival + mode_play_rush > 0) {
        ui_button_update(
            (float *)&position, (ui_button_t *)&tutorial_button);
        position.y += 28.0f;
    }
}

